      medicationInjection:{ label: "Injections",                  perUnit: true,  cents: 1000 },
      bathSmall:          { label: "Bath before pickup (<50 lb)", perUnit: false, cents: 3000 },
      bathLarge:          { label: "Bath before pickup (50 lb+)", perUnit: false, cents: 4000 },
      transport:          { label: "Pickup / drop-off (each way)",perUnit: false, cents: 1500 },
